#include <Adafruit_NeoPixel.h>

// RGB Mood Light — cycles a strip of WS2812B LEDs through colors.

const int DATA_PIN = 6;
const int NUM_LEDS = 8; // change to match your actual strip length

Adafruit_NeoPixel strip(NUM_LEDS, DATA_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  strip.begin();
  strip.setBrightness(80); // 0-255 — keep it modest, full brightness is very bright
  strip.show(); // initialize all pixels to 'off'
}

void loop() {
  setAllPixels(strip.Color(255, 0, 0));   // red
  delay(1000);
  setAllPixels(strip.Color(0, 255, 0));   // green
  delay(1000);
  setAllPixels(strip.Color(0, 0, 255));   // blue
  delay(1000);
  setAllPixels(strip.Color(255, 120, 0)); // warm amber
  delay(1000);
}

void setAllPixels(uint32_t color) {
  for (int i = 0; i < NUM_LEDS; i++) {
    strip.setPixelColor(i, color);
  }
  strip.show(); // nothing changes on the physical strip until show() is called
}
